  for (i = -6; i <= 6; i++) { var w2 = R(Math.sqrt(36 - i * i)); px(kx - w2, ky + i, w2 * 2, 1, '#c98f1c'); }
  for (i = -5; i <= 4; i++) { var w3 = R(Math.sqrt(25 - (i + 0.5) * (i + 0.5))); px(kx - w3, ky + i, w3 * 2, 1, '#ffc94a'); }
