function renderUI() {
  trimLabels();
  uctx.setTransform(DPR2, 0, 0, DPR2, 0, 0);
  uctx.clearRect(0, 0, VW, VH);
  uctx.textAlign = 'left'; uctx.textBaseline = 'alphabetic';
  var taken = [];
  function hits(r) {
    for (var k = 0; k < taken.length; k++) {
      var o = taken[k];
      if (r.x < o.x + o.w && r.x + r.w > o.x && r.y < o.y + o.h && r.y + r.h > o.y) return true;
    }
    return false;
  }
  for (var i = 0; i < uiQ.length; i++) {
    var q = uiQ[i];
    var cx = Math.round(uiX(q.x, q.y, q.dx)), cy = Math.round(uiY(q.x, q.y, q.z, q.dy));
    if (cx < -160 || cx > VW + 160 || cy < -60 || cy > VH + 60) continue;
    uctx.globalAlpha = q.a;
    if (q.t === 1 || q.t === 2 || q.t === 4 || q.t === 5) {     /* v2.18-deneme: t=5 gri "⏸ Bekliyor" rozeti */
      var fs = q.t === 2 ? 9.5 : q.t === 4 ? 10.5 : q.t === 5 ? 9 : 10;
      uctx.font = uiFont(fs);
      var w = Math.round(uctx.measureText(q.s).width) + 9, h = fs + 6;
      var rect = { x: cx - w / 2, y: cy - h, w: w, h: h };
      if (VW && w < VW - 8) { rect.x = clamp(rect.x, 4, VW - w - 4); cx = rect.x + w / 2; }   /* v0.9: ekrandan taşmasın */
      for (var tr = 0; tr < 5 && hits(rect); tr++) rect.y -= h + 2;
      if (hits(rect)) continue;                       /* yer yoksa hiç çizme */
      taken.push(rect);
      cy = rect.y + h;
      if (FINE) {                                     /* v2.13 ince: köşesi kırık, gölgeli, tek çizgi kenarlı sade levha */
        uctx.fillStyle = 'rgba(6,16,24,.35)'; uctx.fillRect(rect.x + 2, rect.y + h, w - 3, 2);
        uctx.fillStyle = '#0a1a27'; uctx.fillRect(rect.x + 1, rect.y, w - 2, h); uctx.fillRect(rect.x, rect.y + 1, w, h - 2);
        uctx.fillStyle = q.t === 5 ? 'rgba(66,70,74,.94)' : q.t === 4 ? 'rgba(58,16,12,.96)' : q.t === 1 ? 'rgba(22,44,64,.95)' : 'rgba(31,62,88,.95)';
        uctx.fillRect(rect.x + 1, rect.y + 1, w - 2, h - 2);
        uctx.fillStyle = 'rgba(255,255,255,.10)'; uctx.fillRect(rect.x + 2, rect.y + 1, w - 4, 1);
      } else {
      uctx.fillStyle = '#0a1a27'; uctx.fillRect(rect.x, rect.y, w, h);
      uctx.fillStyle = q.t === 5 ? 'rgba(66,70,74,.92)' : q.t === 4 ? 'rgba(58,16,12,.94)' : q.t === 1 ? 'rgba(20,41,60,.92)' : 'rgba(29,58,82,.92)';
      uctx.fillRect(rect.x + 2, rect.y + 2, w - 4, h - 4);
      }
      /* kilim çentiği: üst kenarda iki altın nokta */
      uctx.fillStyle = q.t === 1 ? '#c9a15e' : q.t === 5 ? '#9a9ea2' : '#7a9ab0';
      uctx.fillRect(rect.x + 2, rect.y + 2, 2, 1); uctx.fillRect(rect.x + w - 4, rect.y + 2, 2, 1);
      uctx.fillStyle = q.c || '#f4e9d2';
      uctx.fillText(q.s, Math.round(textAt(uctx, q.s, cx)), cy - 5);
    } else {
      uctx.font = uiFont(q.sz);
      uctx.lineWidth = 3; uctx.strokeStyle = q.o || 'rgba(10,26,39,.92)'; uctx.lineJoin = 'round';
      var tx = Math.round(textAt(uctx, q.s, cx));
      uctx.strokeText(q.s, tx, cy);
      uctx.fillStyle = q.c || '#f4e9d2';
      uctx.fillText(q.s, tx, cy);
    }
  }
  uctx.globalAlpha = 1;
  uiQ.length = 0;
}
window.addEventListener('resize', resize);
window.addEventListener('orientationchange', function () { setTimeout(resize, 150); });

/* izometrik */
var TW = 24, TH = 12;
function pX(x, y) { return (x - y) * (TW / 2); }
function pY(x, y, z) { return (x + y) * (TH / 2) - (z || 0); }

/* v2.5.1 — iPhone: iki parmak sıkıştırma ya da yazı kutusu odağı sayfayı yakınlaştırıp kaydırınca üst şerit ve alt
   sekmeler ekrandan taşıyordu. Sıkıştırma engellenir; yazı kutusundan çıkınca ölçek ve kaydırma sıfırlanır. */
(function () {
  ['gesturestart', 'gesturechange'].forEach(function (e) { document.addEventListener(e, function (ev) { ev.preventDefault(); }, { passive: false }); });
  function typing() { var a = document.activeElement; return !!(a && /INPUT|TEXTAREA/.test(a.tagName) && a.type !== 'range'); }
  function resetZoom() {
    var m = document.querySelector('meta[name=viewport]');
    if (m) { var c = m.getAttribute('content'); m.setAttribute('content', c.replace(/,?\s*x=1$/, '') + ',x=1'); setTimeout(function () { m.setAttribute('content', c); }, 60); }
    if (window.scrollX || window.scrollY) window.scrollTo(0, 0);
  }
  document.addEventListener('focusout', function (ev) { if (ev.target && /INPUT|TEXTAREA/.test(ev.target.tagName)) setTimeout(function () { if (!typing()) resetZoom(); }, 80); });
  window.addEventListener('scroll', function () { if (!typing() && (window.scrollX || window.scrollY)) window.scrollTo(0, 0); });
  if (window.visualViewport) window.visualViewport.addEventListener('resize', function () { if (window.visualViewport.scale > 1.01 && !typing()) resetZoom(); });
  /* v2.15.2 — iPhone Safari çift dokunmada sayfayı yakınlaştırıyordu (sıkıştırma kapalı olduğu için geri de dönülemiyordu).
     Düğme dışındaki hızlı ikinci dokunuşun varsayılanı engellenir; düğmeler CSS touch-action:manipulation ile korunur. */
  var lastTap = 0;
  document.addEventListener('touchend', function (ev) {
    var now = Date.now(), t = ev.target, ui = t && t.closest && t.closest('button,a,input,select,textarea,label');
    if (!ui && !typing() && now - lastTap < 350) ev.preventDefault();
    lastTap = now;
  }, { passive: false });
  document.addEventListener('dblclick', function (ev) { if (!typing()) ev.preventDefault(); }, { passive: false });
})();

/* ---------------- girdi ---------------- */
var keys = {};
/* v0.3 — hareket göstergesi + kontrol eğitimi */
var moveDir = { on: false, x: 0, y: 0 }, ctrlWalk = 0, ctrlT = 0;
var inputMode = (window.matchMedia && matchMedia('(pointer: coarse)').matches) ? 'touch' : 'key';
function typing(e) { var tg = e.target && e.target.tagName; return tg === 'INPUT' || tg === 'TEXTAREA'; }
window.addEventListener('keydown', function (e) {
  if (typing(e)) return;
  keys[e.key.toLowerCase()] = true;
  if (/^(w|a|s|d|arrow)/.test(e.key.toLowerCase()) && inputMode !== 'key') { inputMode = 'key'; if (el.coach) el.coach.dataset.k = ''; }
  if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].indexOf(e.key.toLowerCase()) >= 0) e.preventDefault();
});
window.addEventListener('keyup', function (e) { keys[e.key.toLowerCase()] = false; });
var stick = { active: false, id: -1, bx: 0, by: 0, dx: 0, dy: 0 };
/* v2.17 — dekor düzenleme modu durumu (ayrıntılar DEKOR DÜZENLEME MODU bölümünde) */
var ARR = { on: false, sel: -1, drag: null, pan: null, mask: null, chest: false, cam: null, last: null };
cvs.addEventListener('pointerdown', function (e) {
  cvs.setPointerCapture(e.pointerId);
  if (ARR.on) { arrDown(e); return; }               /* v2.17: düzenleme modunda joystick yok: süs sürükle / kamerayı kaydır */
  petTapStart(e);                                   /* v2.18-deneme: hayvana dokun → sev */
  tarifTapStart(e);                                 /* v2.18-deneme: ocağa dokun → Tarif Defteri */
  adTapStart(e); lokTapStart(e);                    /* v2.18-deneme: İlan Bürosu'na dokun → panel (v2.19: lokanta tabelası/menü tahtası) */
  if (inputMode !== 'touch') { inputMode = 'touch'; if (el.coach) el.coach.dataset.k = ''; }
  stick.active = true; stick.id = e.pointerId; stick.bx = e.clientX; stick.by = e.clientY; stick.dx = 0; stick.dy = 0;
});
cvs.addEventListener('pointermove', function (e) {
  if (ARR.on) { arrMove(e); return; }
  if (!stick.active || e.pointerId !== stick.id) return;
  var dx = e.clientX - stick.bx, dy = e.clientY - stick.by, L = Math.hypot(dx, dy), Rr = 60;
  if (L > Rr) { stick.bx += dx * (1 - Rr / L); stick.by += dy * (1 - Rr / L); dx = e.clientX - stick.bx; dy = e.clientY - stick.by; L = Rr; }
  stick.dx = L > 6 ? dx / Rr : 0; stick.dy = L > 6 ? dy / Rr : 0;
});
function stickEnd(e) { if (!e || e.pointerId === stick.id) { stick.active = false; stick.id = -1; stick.dx = 0; stick.dy = 0; } }
cvs.addEventListener('pointerup', function (e) { if (ARR.on) arrUp(e, false); else { petTapEnd(e); tarifTapEnd(e); adTapEnd(e); lokTapEnd(e); } stickEnd(e); });   /* v2.18-deneme: ocağa dokunma */
cvs.addEventListener('pointercancel', function (e) { if (ARR.on) arrUp(e, true); stickEnd(e); });
cvs.addEventListener('contextmenu', function (e) { e.preventDefault(); });

/* ---------------- ses ---------------- */
/* =========================================================
   SES MOTORU v2 — 0.1 sürümü
   • Tek master gain + 3 kademeli ses seviyesi (kapalı / kısık / açık)
   • Her kullanıcı dokunuşunda AudioContext açılır ve resume edilir
     (iOS/Safari ve mobil Chrome'un otomatik oynatma kilidi için)
   • Zarf (attack/decay) ile tık sesi yok, kare dalga yumuşatılmış
   ========================================================= */
var AC = null, masterGain = null, soundOn = true, volLvl = 2;   /* 0 kapalı, 1 kısık, 2 açık */
/* v2.3 — üç ayrı kanal: müzik, efektler (satış, taşıma, arayüz), ortam (dalga, martı, çan). Her biri ayarlardan
   ayrı kısılır. Efekt kanalında sıkıştırıcı var: çok tezgâhta aynı anda çalan sesler patlamaz. */
var VOL = { mus: 0.8, sfx: 0.7, amb: 0.7 };
var musBus = null, sfxBus = null, ambBus = null, sfxMul = 1, sfxCtx = null, storyMute = false;
function setupBuses() {
  var comp = AC.createDynamicsCompressor();
  comp.threshold.value = -20; comp.knee.value = 12; comp.ratio.value = 6; comp.attack.value = 0.003; comp.release.value = 0.2;
  comp.connect(masterGain);
  sfxBus = AC.createGain(); sfxBus.connect(comp);
  ambBus = AC.createGain(); ambBus.connect(masterGain);
  musBus = AC.createGain(); musBus.connect(masterGain);
  applyBusVol();
}
function applyBusVol() {
  if (!AC || !sfxBus) return;
  var t = AC.currentTime;
  var q = storyMute ? 0 : 1;                       /* v2.4: ara sahnede oyunun müziği ve ortamı tamamen susar */
  var tc = q !== applyBusVol.q ? 0.35 : 0.05; applyBusVol.q = q;   /* v2.13: ara sahneye giriş/çıkışta yumuşak (≈1 sn) */
  try { musBus.gain.setTargetAtTime(VOL.mus * q, t, tc); sfxBus.gain.setTargetAtTime(VOL.sfx, t, 0.03); ambBus.gain.setTargetAtTime(VOL.amb * 1.4 * q, t, tc); }
  catch (e) { musBus.gain.value = VOL.mus * q; sfxBus.gain.value = VOL.sfx; ambBus.gain.value = VOL.amb * 1.4 * q; }
}
var VOLS = [0, 0.22, 0.5];
var audioReady = false;

function ensureAudio() {
  try {
    if (!AC) {
      var Ctor = window.AudioContext || window.webkitAudioContext;
      if (!Ctor) return false;
      AC = new Ctor();
      masterGain = AC.createGain();
      masterGain.gain.value = VOLS[volLvl] || 0;
      masterGain.connect(AC.destination);
      setupBuses();
    }
    if (AC.state === 'suspended' && AC.resume) AC.resume();
    audioReady = AC.state === 'running';
    return audioReady;
  } catch (e) { return false; }
}
function applyVolume() {
  soundOn = volLvl > 0;
  if (masterGain && AC) {
    try { masterGain.gain.setTargetAtTime(VOLS[volLvl] || 0, AC.currentTime, 0.02); }
    catch (e) { masterGain.gain.value = VOLS[volLvl] || 0; }
  }
}
/* her dokunuş/tuş sesi açma şansı verir — mobilde kritik */
['pointerdown', 'touchstart', 'keydown', 'mousedown'].forEach(function (ev) {
  window.addEventListener(ev, function () { ensureAudio(); }, { passive: true });
});
document.addEventListener('visibilitychange', function () {
  if (!document.hidden) ensureAudio();
});

/* --- temel ton: zarflı osilatör --- */
function tone(f, d, type, v, o) {
  if (!soundOn || !ensureAudio()) return;
  o = o || {};
  try {
    var t0 = AC.currentTime + (o.at || 0);
    var osc = AC.createOscillator(), g = AC.createGain();
    osc.type = type || 'square';
    osc.frequency.setValueAtTime(f, t0);
    if (o.to) osc.frequency.exponentialRampToValueAtTime(Math.max(1, o.to), t0 + d);
    var peak = Math.max(0.0001, (v === undefined ? 0.5 : v) * (o.dst ? 1 : sfxMul));
    var atk = o.atk === undefined ? 0.008 : o.atk;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(peak, t0 + atk);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + d);
    var node = osc;
    if (o.lp) {                                   /* alçak geçiren: sert kareyi yumuşatır */
      var bq = AC.createBiquadFilter();
      bq.type = 'lowpass'; bq.frequency.value = o.lp;
      node.connect(bq); node = bq;
    }
    node.connect(g); g.connect(o.dst || sfxBus || masterGain);
    osc.start(t0); osc.stop(t0 + d + 0.02);
  } catch (e) { }
}
/* --- gürültü: su sıçraması, satır darbesi, kepenk --- */
var _noiseBuf = null;
function noiseBuffer() {
  if (_noiseBuf) return _noiseBuf;
  var n = Math.floor(AC.sampleRate * 0.5);
  _noiseBuf = AC.createBuffer(1, n, AC.sampleRate);
  var ch = _noiseBuf.getChannelData(0);
  for (var i = 0; i < n; i++) ch[i] = Math.random() * 2 - 1;
  return _noiseBuf;
}
function noise(d, v, o) {
  if (!soundOn || !ensureAudio()) return;
  o = o || {};
  try {
    var t0 = AC.currentTime + (o.at || 0);
    var src = AC.createBufferSource(); src.buffer = noiseBuffer();
    var bq = AC.createBiquadFilter();
    bq.type = o.type || 'lowpass';
    bq.frequency.setValueAtTime(o.f || 1200, t0);
    if (o.to) bq.frequency.exponentialRampToValueAtTime(Math.max(40, o.to), t0 + d);
    bq.Q.value = o.q || 1;
    var g = AC.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0001, v * (o.dst ? 1 : sfxMul)), t0 + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + d);
    src.connect(bq); bq.connect(g); g.connect(o.dst || sfxBus || masterGain);
    src.start(t0); src.stop(t0 + d + 0.02);
  } catch (e) { }
}
function melody(notes, type, v, lp) {
  for (var i = 0; i < notes.length; i++)
    tone(notes[i][0], notes[i][1], type || 'square', v === undefined ? 0.4 : v, { at: notes[i][2], lp: lp || 2400 });
}

