/* v2.22-deneme — HİZMET SAHASI KALDIRILDI (LOKANTA_V3_PLAN.md): yerine Sahil Lokantası yayılır. Beş bina da "kaldırılan" sayılır:
   eski kayıtta kurulu binanın bedeli SERV_GONE göçüyle iade edilir (servLoad → servRefund). Etkileri taşınmaz; açtıkları kilitler
   (turist, toptancı, şirket kontratı) bina şartı olmadan kendi seviye koşullarıyla gelir (servUnlock). Kod şimdilik bayrakla uyur. */
var SERV_OFF = true;
if (SERV_OFF) { SERV.forEach(function (d) { SERV_GONE[d.id] = null; SERV_GONE_COST[d.id] = d.lv.map(function (q) { return q.c; }); }); SERV.length = 0; }
function sdef(id) { for (var i = 0; i < SERV.length; i++) if (SERV[i].id === id) return SERV[i]; return null; }

/* Bina durumu (§40 ServiceBuildingState) — kurulmamış binalar listede yok. */
var servState = {};
function sBuilt(id) { var s = servState[id]; return !!(s && s.lvl > 0); }
function sLvl(id) { var s = servState[id]; return s ? s.lvl : 0; }
function servCount() { var n = 0; for (var k in servState) if (servState[k] && servState[k].lvl > 0) n++; return n; }

/* Toplam etki: kurulu her binanın mevcut seviyesindeki mod'ları toplar (§34 toplamsal). */
var _seCache = null, _seT = -1;
function servMods() {
  if (_seT === gameT && _seCache) return _seCache;
  var out = {};
  for (var i = 0; i < SERV.length; i++) {
    var d = SERV[i], st = servState[d.id];
    if (!st || st.lvl < 1) continue;
    var m = d.lv[st.lvl - 1].mod || {};
    for (var k in m) out[k] = (out[k] || 0) + m[k];
  }
  _seCache = out; _seT = gameT;
  return out;
}
function servEff(key) { return servMods()[key] || 0; }
/* Bir kilit açık mı (toptanci / turist / ctr) */
function servUnlock(tag) {
  if (SERV_OFF) return true;                                   /* v2.22-deneme: saha yok, kilit de yok */
  if (tag === 'turist' && adLive('panayir')) return true;     /* v2.18-deneme: Panayır Standı günü turist geçici açık */
  for (var i = 0; i < SERV.length; i++) {
    var d = SERV[i], st = servState[d.id];
    if (!st || st.lvl < 1) continue;
    if (d.lv[st.lvl - 1].unl === tag) return true;
  }
  return false;
}

/* Bir bina şu an kurulabilir mi + neden değil (§37 tek satır kilit sebebi) */
function servLockReason(d) {
  if (sBuilt(d.id)) return null;
  var ok = false;
  for (var i = 0; i < PLOTS.length; i++) {
    var p = PLOTS[i];
    if (p.b || !plotActive(p)) continue;
    if (p.allow.indexOf(d.id) >= 0) { ok = true; break; }
  }
  if (d.need && servCount() < d.need) return T('needServ', { n: d.need });
  if (!ok) {
    var z = -1;
    for (var j = 0; j < PLOTS.length; j++) if (PLOTS[j].allow.indexOf(d.id) >= 0) { z = PLOTS[j].z; break; }
    for (var j2 = 0; j2 < PLOTS.length; j2++) {
      var q = PLOTS[j2];
      if (q.allow.indexOf(d.id) >= 0 && AREAS[q.z].locked) { z = q.z; break; }
    }
    if (z >= 0 && AREAS[z].locked) return T('needArea', { n: NM(AREAS[z].n) });
    return T('noPlot');
  }
  return null;
}
function servFreePlots(id) {
  var out = [];
  for (var i = 0; i < PLOTS.length; i++) {
    var p = PLOTS[i];
    if (p.b || !plotActive(p)) continue;
    if (p.allow.indexOf(id) >= 0) out.push(p);
  }
  return out;
}
function servBuild(id, plot) {
  var d = sdef(id); if (!d || sBuilt(id) || !plot || plot.b) return false;
  if (insBusy(id)) return false;
  plot.b = id;
  if (!insOff()) { insStart(id, 1, { p: plot.id }); return true; }   /* v2.18-deneme: parsel ayrılır, bina 1 gün sonra kurulur */
  servState[id] = { lvl: 1, plot: plot.id, cons: 2.2, fresh: 1, nextT: d.lv[0].ivl || 0, flash: 0 };
  _seT = -1; rebuildCounters(); reassignWorkers();
  sfx.build(); addPuff(plot.x, plot.y, '#ffc94a');
  toast(T('servBuilt', { n: NM(d.n) }));
  return true;
}
function servUp(id) {
  var d = sdef(id), st = servState[id];
  if (!d || !st || st.lvl >= 5 || insBusy(id)) return false;
  if (!insOff()) { insStart(id, st.lvl + 1); return true; }   /* v2.18-deneme: eski seviyeyle çalışır, yeni seviye L gün sonra */
  st.lvl++; st.cons = 1.3; st.fresh = 0; st.flash = 1.8;
  st.nextT = d.lv[st.lvl - 1].ivl || 0;
  _seT = -1; rebuildCounters(); reassignWorkers();
  var p = plotById(st.plot);
  if (p) addPuff(p.x, p.y, '#ffc94a');
  sfx.build(); toast(T('servUp', { n: NM(d.n), l: st.lvl }));
  return true;
}
/* §32.1 — ücretsiz taşıma, seviye korunur */
function servMove(id, plot) {
  var st = servState[id]; if (!st || !plot || plot.b) return false;
  var old = plotById(st.plot); if (old) old.b = null;
  plot.b = id; st.plot = plot.id; st.cons = 0;
  sfx.build(); addPuff(plot.x, plot.y, '#9df5b0');
  toast(T('servMoved', { n: NM(sdef(id).n) }));
  return true;
}
/* §41 — kayıt: hiçbir bina otomatik satın alınmaz, para kesilmez */
function servSave() {
  var out = [];
  for (var i = 0; i < SERV.length; i++) {
    var st = servState[SERV[i].id];
    if (st && st.lvl > 0) out.push([SERV[i].id, st.lvl, st.plot]);
  }
  return out;
}
/* oyuncunun bir binaya lv seviyeye kadar ödediği (indirimli) tutar */
function servSpent(costs, lv) { var t = 0; for (var i = 0; i < lv && i < costs.length; i++) t += upCost(sCost(costs[i])); return t; }
function servCosts(d) { return d.lv.map(function (q) { return q.c; }); }
var servRefund = 0;
function servLoad(arr) {
  servState = {}; servRefund = 0; _seT = -1;
  for (var i = 0; i < PLOTS.length; i++) PLOTS[i].b = null;
  if (!arr || !arr.length) return;
  /* v1.4 göç: kaldırılan bina → birleştiği binanın seviyesi en az onunki kadar olur.
     paid[bina] = oyuncunun o binaya fiilen koyduğu toplam (kendi seviyeleri + ona katılan eski bina).
     İade = paid − yeni seviyenin değeri (kurulabildiyse) ya da paid'in tamamı (parsel yoksa); asla ödenenden fazla değil. */
  var lvIn = {}, plIn = {}, paid = {}, gone = [];
  for (var g = 0; g < arr.length; g++) {
    var rg = arr[g]; if (!rg) continue;
    var lg = clamp(parseInt(rg[1], 10) || 1, 1, 5);
    if (SERV_GONE.hasOwnProperty(rg[0])) gone.push([rg[0], lg]);
    else if (sdef(rg[0]) && lg > (lvIn[rg[0]] || 0)) { lvIn[rg[0]] = lg; plIn[rg[0]] = rg[2]; }
  }
  for (var k0 in lvIn) paid[k0] = servSpent(servCosts(sdef(k0)), lvIn[k0]);
  for (g = 0; g < gone.length; g++) {
    var gid = gone[g][0], glv = gone[g][1], into = SERV_GONE[gid], spent = servSpent(SERV_GONE_COST[gid], glv);
    if (into) { lvIn[into] = Math.max(lvIn[into] || 0, glv); paid[into] = (paid[into] || 0) + spent; }
    else servRefund += spent;                                   /* birleşeceği bina yok (yakıt, tersane) → tamamı iade */
  }
  for (var key in lvIn) {
    var d = sdef(key), lv = clamp(lvIn[key], 1, 5);
    var p = plotById(plIn[key]);
    if (!p || p.b || !plotActive(p) || p.allow.indexOf(d.id) < 0) {   /* geçersiz/kilitli parsel → uygun boşa taşı */
      var alt = servFreePlots(d.id);
      p = alt.length ? alt[0] : null;
    }
    if (!p) { servRefund += paid[key] || 0; continue; }         /* yer yoksa ödenen her şey iade */
    p.b = d.id;
    servState[d.id] = { lvl: lv, plot: p.id, cons: 0, nextT: d.lv[lv - 1].ivl || 0, flash: 0 };
    servRefund += Math.max(0, (paid[key] || 0) - servSpent(servCosts(d), lv));
  }
  _seT = -1;
}
/* v1.2 §9 — gün / depo / hedef stok yüklemesi */
function loadDay(d) {
  if (d && d.day) {
    day.n = Math.max(1, parseInt(d.day[0], 10) || 1);
    day.t = clamp(parseFloat(d.day[1]) || 0, 0, DAY_LEN - 1);
    day.market = !!d.day[2] && isMarketDay(day.n);
    day.feat = custById(d.day[3]) ? d.day[3] : null;
    var sps = String(d.day[4] || '').split(',').filter(function (q) { return specById(q); });
    if (sps.length === 2) {
      day.spec = sps; day.normals = parseInt(d.day[6], 10) || 0;
      var sp0 = parseInt(d.day[5], 10) || 0;
      day.sp = sp0 === 2 ? 1 : sp0 === 3 ? 4 : sp0;   /* müşteriler kaydedilmez: yarım kalan adımı güvenle sürdür */
      day.popT = 0;
    } else day.spec = null;
  }
  day.phase = 'play'; day.ph = 0; day.st = newDayStats(); day.last = null;
  if (d && d.stalls) {
    for (var j = 0; j < d.stalls.length; j++) {
      var c = counterByKey(d.stalls[j][0]);
      if (c) c.open = !!d.stalls[j][1];
    }
  }
  openStarterStall();
}

/* §41 doğrulama: parsel kasa güvenli alanını veya kuyruğu işgal etmiyor */
function servValidate() {
  var bad = [];
  for (var i = 0; i < PLOTS.length; i++) {
    var p = PLOTS[i];
    if (dist2(p.x, p.y, safe.x, safe.y) < 4.0) bad.push(p.id + ':safe');
    for (var k = 0; k < counters.length; k++) {
      var c = counters[k];
      if (Math.abs(p.x - c.x) < 1.2 && Math.abs(p.y - c.y) < 1.2) bad.push(p.id + ':queue');
      if (p.x > 10.0 && p.x < 14.8) bad.push(p.id + ':lane');
    }
  }
  return bad;
}

/* §34 / §38.2 — servis geliri: ana balık gelirinin %30'unu aşamaz */
var fishRate = 0, servRate = 0;
function noteFishIncome(v) { fishRate += v; }
function servTick(dt) {
  var dec = Math.pow(0.5, dt / 30);                 /* ~30 sn yarı ömür */
  fishRate *= dec; servRate *= dec;
  var cap = Math.max(12, fishRate * 0.30);
  for (var i = 0; i < SERV.length; i++) {
    var d = SERV[i], st = servState[d.id];
    if (!st || st.lvl < 1) continue;
    if (st.cons > 0) st.cons = Math.max(0, st.cons - dt);
    if (st.flash > 0) st.flash = Math.max(0, st.flash - dt);
    var L = d.lv[st.lvl - 1];
    if (L.cook) { st.nextT -= dt; if (st.nextT <= 0) { st.nextT = L.ivl * rnd(0.85, 1.15); restoCook(d, st, L); } continue; }
    if (!L.inc || !L.ivl) continue;
    st.nextT -= dt;
    if (st.nextT > 0) continue;
    st.nextT = L.ivl * rnd(0.8, 1.25);
    if (servRate >= cap) continue;                  /* tavan: AFK para makinesi olmaz */
    var pay = Math.round(L.inc * (1 + repLevel() * 0.02));
    S.cash += pay; servRate += pay; earn(pay);
    var p = plotById(st.plot);
    if (p) { addFloat(p.x, p.y - 0.4, '+' + money(pay), '#9df5b0'); st.flash = 0.8; }
  }
}

/* v1.4 — Restoran pasif para basmaz: yalnız FAZLA malı pişirip satar. Fazla = depo %60'tan doluysa en kalabalık
   raf, ya da tezgâh tamponu %75'ten doluysa o tezgâh. Fazla yoksa boş bekler (oyuncu bunu görür). */
function restoSurplus() {
  var out = [], k;
  if (DEPOT.lvl && depotCount() > depotCap() * 0.6) {
    var keys = Object.keys(DEPOT.shelf).sort(function (a, b) { return DEPOT.shelf[b] - DEPOT.shelf[a]; });
    if (keys.length) out.push({ depot: keys[0] });
  }
  for (k = 0; k < counters.length; k++) {
    var c = counters[k];
    if (!AREAS[c.z].locked && shelfN(c) > counterMax(c) * 0.75) out.push({ c: c });
  }
  return out;
}
function restoCook(d, st, L) {
  var got = 0, gain = 0, src = restoSurplus(), guard = 0, plain = 0, plainGain = 0, dishes = [], dl = null;
  while (got < L.cook && src.length && guard++ < 40) {
    var s0 = src[0], it = null;
    if (s0.depot) { if (depotCount() > depotCap() * 0.6) it = depotTake(s0.depot); }
    else if (shelfN(s0.c) > counterMax(s0.c) * 0.75) it = ctrPopShelf(s0.c);
    if (!it) { src.shift(); continue; }
    var base = prodValue(it.k, it.f), dr = tarifRestoPick(it.f);   /* v2.18-deneme §A: menüdeki tarif + kiler → yemek */
    if (dr) {
      tarifRestoUse(dr);
      var dv = base * L.cmul * dr.m;
      gain += dv; got++;
      if (!(dl = dishes.filter(function (x) { return x.r === dr; })[0])) dishes.push(dl = { r: dr, n: 0, v: 0 });
      dl.n++; dl.v += dv;
    } else { gain += base * L.cmul; got++; plain++; plainGain += base * L.cmul; }
  }
  st.cooked = got;
  var p = plotById(st.plot);
  if (!got) { if (p) addFloat(p.x, p.y - 0.4, T('restoIdle'), '#c9bfae'); return 0; }
  var pay = Math.round(gain);
  S.cash += pay; earn(pay); noteDayIncome(pay);
  if (p) {
    dishes.forEach(function (x, i) {
      addFloat(p.x, p.y - 0.4 - i * 0.32, '🍲 ' + NM(x.r.n) + (x.n > 1 ? ' ×' + x.n : '') + ' +' + money(Math.round(x.v)), '#ffd98a');
      RFX.push({ x: p.x, y: p.y, t: -i * 0.35, d: x.r.id });
    });
    if (plain) addFloat(p.x, p.y - 0.4 - dishes.length * 0.32, '🍽 ' + plain + ' → +' + money(Math.round(plainGain)), '#9df5b0');
    st.flash = 0.8;
  }
  return pay;
}

/* =========================================================
   v2.18-deneme — İNŞAAT
   Hizmet binaları (BİNA sekmesi) ve meydan binaları (YAPI › Meydan) satın alınınca hemen değil, L gün sonra hazır olur
   (hedef seviye L → L oyun günü). Hem ilk kurulum hem her seviye yükseltmesi. Kapsam dışı: istasyon yükseltmeleri (YÜKSELT),
   YAPI › Geliştirme/Dekor kartları, bölge (ALAN) açılışları.
   • Para satın alırken bugünkü gibi düşer. Gün sayımı endDay'de azalır; gün başında (beginNextDay) biten bina tamamlanır.
   • İlk kurulumda bina çalışmaz (hiçbir etkisi yok; parsel ayrılır). Yükseltmede eski seviye çalışır, yeni seviye bitince devreye girer.
   • Bir bina aynı anda tek inşaat: kartı kilitli ("🏗 İnşaatta · N gün").
   • Durum: S.insaat = { bina: { lv: hedef seviye, left: kalan gün [, p: ilk kurulumda parsel] } }. Bina kimlikleri: hizmet binaları
     (buzhane restoran nakliye koop mezat) + meydan (hut depot whall office).
   • Hedef/başarım/gazete sayaçları zaten kurulu SEVİYEYE bakar (servCount, HUT.lvl, DEPOT.lvl, WHALL.built, M.office);
     bina seviyesi yalnız tamamlanınca yükseldiği için hepsi tamamlanmada sayılır.
   • Test: window.HK_INSAAT_OFF = 1 → inşaat anında biter (eski davranış).
   • Çizim: klasik iskele burada; ince mod için HKA.drawScaffold(o) kancası (o: {id, x, y, w, h, left, lv, t, up, hh};
     up = yükseltme (altta bina var), hh = iskele yüksekliği px). Etiketi ("İnşaat · N gün") oyun çizer.
   ========================================================= */
var INS_MEYDAN = ['hut', 'depot', 'whall', 'office', 'ads'];   /* ads = İlan Bürosu (Bölüm C) */
function insOff() { return !!window.HK_INSAAT_OFF; }
function insMap() { if (!S.insaat || typeof S.insaat !== 'object') S.insaat = {}; return S.insaat; }
function insBusy(id) { return !!insMap()[id]; }
function insLeft(id) { var e = insMap()[id]; return e ? e.left : 0; }
function insValid(id) { return !!sdef(id) || INS_MEYDAN.indexOf(id) >= 0 || lokIns(id); }
function insDays(n) { return lang === 'tr' ? n + ' gün' : n + (n === 1 ? ' day' : ' days'); }
function insName(id) {
  var d = sdef(id); if (d) return NM(d.n);
  if (lokIns(id)) return lokInsName(id);
  return T(id === 'hut' ? 'hutName' : id === 'depot' ? 'depotName' : id === 'whall' ? 'whall' : id === 'ads' ? 'adName' : 'office');
}
/* kartı kilitle: "🏗 İnşaatta · N gün" */
function insLock(c, id) {
  c.blocked = true; c.owned = false; c.pick = null; c.go = null; c.cost = undefined;
  c.why = T('insLock', { d: insDays(insLeft(id)) });
  return c;
}
function insLockCards(out) {
  var map = { mhut: 'hut', mdep: 'depot', mhal: 'whall', moffice: 'office', mads: 'ads' };
  for (var i = 0; i < out.length; i++) if (out[i] && map[out[i].id] && insBusy(map[out[i].id])) insLock(out[i], map[out[i].id]);
}
/* iskelenin yeri ve boyu (dünya birimi / px) */
function insPos(id, e) {
  if (lokIns(id)) return lokInsPos(id, e);
  var d = sdef(id), st, p, r;
  if (d) {
    st = servState[id]; p = plotById(st ? st.plot : e.p); if (!p) return null;
    r = SERV_MAT[Math.max(1, st ? st.lvl : e.lv) - 1];
    return { x: p.x, y: p.y, w: r.foot * 1.7, h: r.foot * 1.7, hh: Math.max(r.h, SERV_MAT[Math.min(4, e.lv - 1)].h) + 6, up: !!st };
  }
  if (id === 'hut') return { x: HUT.x, y: HUT.y, w: HUT.w + 0.5, h: HUT.h + 0.5, hh: 13 + e.lv * 1.5 + 8, up: HUT.lvl > 0 };
  if (id === 'depot') {
    var dw = e.lv >= 2 ? depotWing(e.lv) : null;                     /* v2.18-deneme: yeni bölme kendi arsasında yükselir */
    if (dw && dw.x !== undefined) return { x: dw.x, y: dw.y, w: dw.w + 0.4, h: dw.h + 0.4, hh: dw.H + 10, up: false };
    return { x: DEPOT.x, y: DEPOT.y, w: DEPOT.w + 0.5, h: DEPOT.h + 0.5, hh: 22 + e.lv * 2, up: DEPOT.lvl > 0 };
  }
  if (id === 'whall') return { x: WHALL.x, y: WHALL.y, w: WHALL.w + 0.5, h: WHALL.h + 0.5, hh: 30, up: false };
  if (id === 'ads') return { x: AD.x, y: AD.y, w: AD.w + 0.5, h: AD.h + 0.5, hh: 30, up: adBuilt() };
  if (id === 'office') return { x: office.x, y: office.y, w: office.w + 0.5, h: office.h + 0.5, hh: 40, up: false };
  return null;
}
function insStart(id, lv, extra) {
  var e = { lv: lv, left: lv };
  if (extra && extra.p) e.p = extra.p;
  insMap()[id] = e;
  var o = insPos(id, e);
  sfx.build(); if (o) addPuff(o.x, o.y, '#ffc94a');
  toast(T('insStart', { n: insName(id), d: insDays(lv) }));
  if (barTab) renderBar();
  return true;
}
/* meydan binası satın alındı (para düşüldü): inşaat başlar; test bayrağı açıksa eski gibi anında */
function insMeydanBuy(id) {
  var lv = id === 'hut' ? HUT.lvl + 1 : id === 'depot' ? DEPOT.lvl + 1 : id === 'ads' ? adLvl() + 1 : 1;
  if (insOff()) { insApply(id, lv, true); return; }
  if (insBusy(id)) return;
  insStart(id, lv);
}
function officeBuy() { if (!insOff()) { if (!insBusy('office')) insStart('office', 1); return; } officeDone(); }
/* seviye gerçekten yükselir: "kuruldu" etkileri (sayaçlar, başarım, hedef) bu noktada başlar */
function insApply(id, lv, instant, e) {
  if (sdef(id)) { servFinish(id, lv, e); return; }
  if (lokIns(id)) { lokApply(id, lv, instant); return; }
  if (id === 'hut') {
    HUT.lvl = lv; sfx.build(); addPuff(HUT.x, HUT.y, '#ffc94a');
    if (instant) toast(T(lv === 1 ? 'hutBuilt' : 'hutUp', { l: lv }));
  } else if (id === 'depot') {
    DEPOT.lvl = lv; sfx.build(); addPuff(DEPOT.x, DEPOT.y, '#ffc94a');
    if (instant) toast(T(lv === 1 ? 'depotBuilt' : 'depotUp', { l: lv, c: depotCap(), n: depotWingName(lv) }));
  } else if (id === 'whall') {
    WHALL.built = true; sfx.build(); addPuff(WHALL.x, WHALL.y, '#ffc94a');
    if (instant) toast(T('whallBuilt'));
  } else if (id === 'ads') {
    S.adLv = lv; sfx.build(); addPuff(AD.x, AD.y, '#ffc94a');
    if (instant) toast(T(lv === 1 ? 'adBuilt' : 'adUp', { l: lv }));
  } else if (id === 'office') {
    if (M && !M.office) officeDone();
  }
}
function servFinish(id, lv, e) {
  var d = sdef(id), st = servState[id], p;
  if (!d) return;
  if (!st) {
    p = plotById(e && e.p);
    if (!p || (p.b && p.b !== id)) p = servFreePlots(id)[0];
    if (!p) return;
    p.b = id;
    servState[id] = { lvl: 1, plot: p.id, cons: 2.2, fresh: 1, nextT: d.lv[0].ivl || 0, flash: 0 };
  } else {
    st.lvl = lv; st.cons = 1.3; st.fresh = 0; st.flash = 1.8; st.nextT = d.lv[lv - 1].ivl || 0;
  }
  _seT = -1; rebuildCounters(); reassignWorkers();
  var pl = plotById(servState[id].plot);
  if (pl) addPuff(pl.x, pl.y, '#ffc94a');
  sfx.build();
}
/* gün sonu: kalan gün bir azalır */
function insDayEnd() {
  var m = insMap(), any = false;
  for (var id in m) if (m[id].left > 0) { m[id].left--; any = true; }
  if (any && barTab) renderBar();
}
/* gün başı (ve yükleme): kalanı 0 olan inşaatlar tamamlanır */
function insDue(silent) {
  var m = insMap(), done = [], id;
  for (id in m) if (m[id].left <= 0) done.push(id);
  if (!done.length) return;
  var msgs = [];
  done.forEach(function (k) {
    var e = m[k]; delete m[k];
    insApply(k, e.lv, false, e);
    msgs.push(T('insReady', { n: insName(k), l: e.lv }));
  });
  _seT = -1;
  if (silent) return;
  try { achCheck(); } catch (er) { }
  msgs.forEach(function (s, i) { if (!i) toast(s); else setTimeout(function () { toast(s); }, i * 2700); });
  if (S.started) save();
  if (barTab) renderBar();
}
function insSave() {
  var o = {}, m = insMap();
  for (var id in m) { var e = m[id]; o[id] = e.p ? { lv: e.lv, left: e.left, p: e.p } : { lv: e.lv, left: e.left }; }
  return o;
}
/* bozuk/eski kayıt güvenli: bilinmeyen bina, tutarsız seviye, geçersiz parsel elenir ya da düzeltilir */
function insLoad(raw) {
  var out = {}; S.insaat = out;
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return;
  for (var id in raw) {
    if (SERV_OFF && Object.prototype.hasOwnProperty.call(raw, id) && SERV_GONE_COST[id] && raw[id] && typeof raw[id] === 'object') {   /* v2.22: inşaatı süren hizmet binası → ödenen seviye iade */
      var gl = clamp(parseInt(raw[id].lv, 10) || 1, 1, SERV_GONE_COST[id].length); servRefund += upCost(sCost(SERV_GONE_COST[id][gl - 1])); continue;
    }
    if (!Object.prototype.hasOwnProperty.call(raw, id) || !insValid(id)) continue;
    var r = raw[id]; if (!r || typeof r !== 'object' || Array.isArray(r)) continue;
    var d = sdef(id), lv, p;
    if (d) { lv = sLvl(id) + 1; if (lv > 5) continue; }
    else if (id === 'hut') { lv = HUT.lvl + 1; if (lv > HUT_LV.length) continue; }
    else if (id === 'depot') { lv = DEPOT.lvl + 1; if (lv > DEPOT_LV.length) continue; }
    else if (id === 'ads') { lv = adLvl() + 1; if (lv > AD_LV.length) continue; }
    else if (lokIns(id)) { lv = lokInsLv(id); if (!lv) continue; }
    else { lv = 1; if (id === 'whall' && WHALL.built) continue; }
    var left = typeof r.left === 'number' && isFinite(r.left) ? clamp(Math.floor(r.left), 0, lv) : lv, e = { lv: lv, left: left };
    if (d && !sBuilt(id)) {
      p = plotById(r.p);
      if (!p || p.b || !plotActive(p) || p.allow.indexOf(id) < 0) { var alt = servFreePlots(id); p = alt.length ? alt[0] : null; }
      if (!p) { servRefund += upCost(sCost(d.lv[0].c)); continue; }
      p.b = id; e.p = p.id;
    }
    out[id] = e;
  }
}
/* ---------- çizim (klasik; ince modda HKA.drawScaffold) ---------- */
function insObj(id, e) {
  var q = insPos(id, e); if (!q) return null;
  return { id: id, x: q.x, y: q.y, w: q.w, h: q.h, hh: q.hh, up: q.up, left: e.left, lv: e.lv, t: gameT };
}
function pushInsaat(push) {
  var m = insMap();
  for (var id in m) (function (k, e) {
    var o = insObj(k, e); if (!o) return;
    push(o.x + o.y + 0.5, function () { drawScaffold(o); insLabel(o); });
  })(id, m[id]);
}
function insLabel(o) { uiText(o.x, o.y, o.hh + 9, T('insLabel', { d: insDays(o.left) }), '#ffd54a', 11, 1, 0, 0, true); }
function insBrace(xa, ya, za, xb, yb, zb, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 1; ctx.beginPath();
  ctx.moveTo(R(pX(xa, ya)), R(pY(xa, ya, za))); ctx.lineTo(R(pX(xb, yb)), R(pY(xb, yb, zb))); ctx.stroke();
}
function drawScaffold(o) {
  var x0 = o.x - o.w / 2, y0 = o.y - o.h / 2, x1 = x0 + o.w, y1 = y0 + o.h, H = o.hh || (18 + Math.min(5, o.lv) * 4), k;
  var wood = '#a8793e', woodD = '#6a4326', plank = '#d2a468', YEL = '#f2c230', BLK = '#1c1c1c';
  function post(x, y, h) { var sx = R(pX(x, y)), sy = R(pY(x, y, 0)); px(sx - 1, sy - h, 2, h, wood); px(sx, sy - h, 1, h, woodD); }
  function rail(xa, ya, xb, yb, z) { isoLine(xa, ya, xb, yb, z, plank, 2); isoLine(xa, ya, xb, yb, z - 1, woodD, 1); }
  /* kuru toprak zemin; ilk kurulumda yükselen temel/duvar (ilerleme = geçen gün oranı) */
  if (!o.up) {
    var prog = clamp(1 - o.left / Math.max(1, o.lv), 0, 1);
    isoQuad(x0, y0, o.w, o.h, 0.4, '#a8966f');
    isoBox(x0 + 0.14, y0 + 0.14, o.w - 0.28, o.h - 0.28, 0.4, 3 + prog * H * 0.5, '#c9a97a', '#8a6a3f', '#a8834d');
    px(R(pX(x1 + 0.1, y1 + 0.05)) - 4, R(pY(x1 + 0.1, y1 + 0.05, 0)) - 3, 8, 2, plank);       /* yerdeki kalas yığını */
    px(R(pX(x1 + 0.1, y1 + 0.05)) - 3, R(pY(x1 + 0.1, y1 + 0.05, 0)) - 5, 7, 2, wood);
  }
  /* arka direkler + arka korkuluk, sonra ön yüzler */
  post(x0, y0, H); rail(x0, y0, x1, y0, H * 0.66); rail(x0, y0, x0, y1, H * 0.66);
  post(x1, y0, H); post(x0, y1, H);
  /* çapraz kalaslar (güney ve doğu yüzler) */
  insBrace(x0, y1, 0, x1, y1, H * 0.66, woodD); insBrace(x1, y1, 0, x0, y1, H * 0.66, woodD);
  insBrace(x1, y0, 0, x1, y1, H * 0.66, woodD); insBrace(x1, y1, 0, x1, y0, H * 0.66, woodD);
  rail(x0, y1, x1, y1, H * 0.34); rail(x0, y1, x1, y1, H * 0.66); rail(x0, y1, x1, y1, H);
  rail(x1, y0, x1, y1, H * 0.34); rail(x1, y0, x1, y1, H * 0.66); rail(x1, y0, x1, y1, H);
  post(x1, y1, H);
  /* sarı-siyah uyarı şeridi: zeminde ve üst korkulukta */
  var n = 10;
  for (k = 0; k < n; k++) {
    var a = k / n, b = (k + 1) / n, c = k % 2 ? BLK : YEL;
    isoLine(x0 + (x1 - x0) * a, y1 + 0.05, x0 + (x1 - x0) * b, y1 + 0.05, 3, c, 3);
    isoLine(x1 + 0.05, y0 + (y1 - y0) * a, x1 + 0.05, y0 + (y1 - y0) * b, 3, c, 3);
    wallQ(x0 + (x1 - x0) * a, y1, x0 + (x1 - x0) * b, y1, H - 4, H - 1, c);
  }
  /* çekiç: ön köşede sallanır, vuruşta kıvılcım */
  var sw = Math.sin(o.t * 9), hx0 = R(pX(x1, y1)) + 2, hy0 = R(pY(x1, y1, H * 0.66)) - 2;
  var ang = -0.5 + sw * 0.8, hx = hx0 + Math.sin(ang) * 7, hy = hy0 - Math.cos(ang) * 7;
  ctx.strokeStyle = '#4a2f1c'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(hx0, hy0); ctx.lineTo(R(hx), R(hy)); ctx.stroke();
  px(R(hx) - 2, R(hy) - 1, 5, 3, '#8d96a0'); px(R(hx) - 2, R(hy) - 1, 5, 1, '#d8dde2');
  if (sw < -0.85) { dot(hx0 + 6, hy0 - 2, '#ffe27a'); dot(hx0 + 8, hy0 + 1, '#ffd54a'); dot(hx0 + 5, hy0 + 3, '#fff3b0'); }
}

/* =========================================================
   v1.2 — BİRLEŞİK SİSTEM (GDD v1.1)
   Merkezi Depo + Otomatik Dağıtım • Balık Pazarı Günü • Sade Gün Geçişi
   Çekirdek döngü değişmez; bu katman tekrarlı taşımayı yönetim kararına çevirir.
   ========================================================= */

/* ---------------- Merkezi Depo (§3) ---------------- */
/* ---------------- Hedef stok + öncelik (§3.2) ---------------- */
/* ---------------- Sade gün geçişi (§2) ---------------- */
var DAY_LEN = 300, MARKET_EVERY = 5, CLOSE_MAX = 22;
var day = {
  n: 1, t: 0, phase: 'play', ph: 0, market: false,
  st: null, last: null
};
function newDayStats() { return { inc: 0, served: 0, lost: 0, fish: 0, by: {}, out: {}, outAt: {}, spec: [] }; }
day.st = newDayStats();
function isMarketDay(n) { return n > 1 && n % MARKET_EVERY === 0; }
function dayNext() { return isMarketDay(day.n + 1); }
function daySpawnOK() { return day.phase === 'play'; }
function dayCustMul() { return (day.market ? 2.2 : 1) * mxFlowMul(); }
function noteDayIncome(v) { day.st.inc += v; }
function noteDaySale(cu) {
  day.st.served++;
  day.st.fish += cu.ord.need;
  var key = cu.ord.f;
  day.st.by[key] = (day.st.by[key] || 0) + cu.ord.need;
}
function noteDayLost() { day.st.lost++; }
/* stok-dışı süre: bekleyen müşteri var ama tezgâhta o ürün yok (§6.1) */
function noteStockOut(dt) {
  for (var i = 0; i < counters.length; i++) {
    var c = counters[i];
    if (AREAS[c.z].locked || !c.fish) continue;
    var waiting = false, j;
    for (j = 0; j < c.slots.length; j++) if (c.slots[j] && c.slots[j].state === 'wait' && c.slots[j].ord.got < c.slots[j].ord.need) { waiting = true; break; }
    if (!waiting) continue;
    var has = false;
    for (j = 0; j < c.buffer.length; j++) if (c.buffer[j].f === c.fish) { has = true; break; }
    if (!has) day.st.out[c.fish] = (day.st.out[c.fish] || 0) + dt;
  }
}
function fmtDur(sec) {
  sec = Math.max(0, Math.round(sec));
  return Math.floor(sec / 60) + ':' + (sec % 60 < 10 ? '0' : '') + (sec % 60);
}
function topSeller() {
  var best = null, bv = 0;
  for (var k in day.st.by) if (day.st.by[k] > bv) { bv = day.st.by[k]; best = k; }
  return best ? { f: best, n: bv } : null;
}
function worstOut() {
  var best = null, bv = 0;
  for (var k in day.st.out) if (day.st.out[k] > bv) { bv = day.st.out[k]; best = k; }
  return best && bv > 1 ? { f: best, t: bv } : null;
}
/* Pazar geçici ayarlarını temizle (§6: kalıcı hedefi ezmez) */
function updateDay(dt) {
  if (day.phase === 'play') {
    day.t += dt;
    noteStockOut(dt);
    if (day.t >= DAY_LEN) { day.phase = 'closing'; day.ph = 0; }
    return;
  }
  if (day.phase === 'closing') {
    day.ph += dt;
    /* yeni müşteri gelmez; mevcutlar tamamlansın. v0.9: günün 2. özel müşterisi işini bitirene kadar beklenir */
    if (specHoldsClose()) return;
    if (!customers.length || day.ph > CLOSE_MAX) { endDay(); }
    return;
  }
  if (day.phase === 'summary' || day.phase === 'prep') return;   /* kart kapanınca ilerler */
  if (day.phase === 'intro') {
    day.ph -= dt;
    if (day.ph <= 0) { day.phase = 'play'; day.t = 0; }
  }
}
/* Mezat Salonu: gün kapanışında tezgâha gitmemiş işlenmiş ürün (hasır tepsilerde
   bekleyen fileto/füme) kabzımal mezatında açık artırmayla satılır. */
function auctionPiles() {
  var out = [], i;
  for (i = 0; i < tables.length; i++) if (!AREAS[tables[i].z].locked) out.push(tables[i].mat);
  if (!AREAS[smoker.z].locked) out.push(smoker.mat);
  return out;
}
function runAuction() {
  var mul = servEff('auction'), cap = Math.round(servEff('auctionN'));
  if (!mul || !cap) return null;
  var piles = auctionPiles(), sold = 0, gain = 0, at = null;
  for (var p2 = 0; p2 < piles.length && sold < cap; p2++) {
    var pile = piles[p2];
    while (sold < cap && pile.items.length) {
      var it = pile.items.pop();
      if (!isGoods(it) || !validItem(it)) continue;
      gain += Math.round(prodValue(it.k, it.f) * mul);
      sold++; at = pile;
    }
  }
  if (!sold) return null;
  sfx.bell();
  S.cash += gain; earn(gain); noteDayIncome(gain); noteFishIncome(gain * 0.5);
  if (at) addFloat(at.x, at.y - 0.6, '+' + money(gain), '#ffe27a');
  return { n: sold, v: gain };
}
/* v0.3 — gün kapanınca kalan müşteriler selamlaşıp ayrılır (kayıp sayılmaz);
   yeni gün "günün müşterisi" ile başlar: o gün bir müşteri tipi daha sık gelir. */
function dismissCustomers() {
  for (var j = 0; j < customers.length; j++) {
    var cu = customers[j];
    if (cu.state === 'leave') continue;
    cu.state = 'leave'; cu.happyLeave = true; cu.leaveT = 0;
  }
  for (var i = 0; i < counters.length; i++) for (var k = 0; k < counters[i].slots.length; k++) counters[i].slots[k] = null;
}
function featPool() {
  var lvl = repLevel();
  return CUST.filter(function (t) { return t.lvl <= lvl && (!t.serv || servUnlock(t.serv)); });
}
function pickFeatured() {
  var pool = featPool().filter(function (t) { return t.id !== day.feat; });
  day.feat = pool.length ? pick(pool).id : null;
}
function custById(id) { for (var i = 0; i < CUST.length; i++) if (CUST[i].id === id) return CUST[i]; return null; }
function endDay() {
  if (TAX.on) taxFinish();                         /* v2.14: kapanışta memur hâlâ limandaysa vergiyi alıp gider */
  if (TAX.over) { TAX.overT = undefined; gameOverTax(); return; }   /* v2.15: liman mühürlendi */
  dismissCustomers();
  var auc = runAuction();
  var insp = mxInspect();                         /* v2.9: gizli müfettiş raporu */
  day.last = {
    insp: insp,
    n: day.n, market: day.market, inc: day.st.inc, served: day.st.served,
    lost: day.st.lost, fish: day.st.fish, top: topSeller(), out: worstOut(), spec: (day.st.spec || []).slice(),
    next: isMarketDay(day.n + 1), auc: auc
  };
  day.last.pet = petDayEnd();                      /* v2.18-deneme: hayvanların mama ücreti */
  if (M && M.office) closeDay();                 /* borsa günü oyun günüyle aynı */
  if (day.n === 1) gzMark('ilkgun', { n: S.served | 0 });   /* v2.16: ilk günün sonu → ertesi sabah gazetesi */
  insDayEnd();                                     /* v2.18-deneme: inşaatlarda kalan gün azalır */
  adDayEnd();                                      /* v2.18-deneme: reklamlarda kalan gün azalır, biten için toast */
  lokDayEnd();                                     /* v2.19-deneme: lokanta rezervasyonu teslim süresi */
  day.phase = 'summary';
  sfx.dayOut();
  gzDayEnd(showDayCard);                           /* v2.16: alınmamış özel sayı gün kartından önce açılır */
  retDayEnd(day.last);                           /* gün geliri ortalaması + gün sonu başarımları */
  save();
}
/* kart kapatılınca: yeni güne geç (pazar günüyse hazırlık ekranı) */
function beginNextDay(skipPrep) {
  day.n++;
  stallNewDay();
  mxNewDay();                                      /* v2.9: veresiye ödemesi, günlük sayaçlar */                                   /* v2.6: bugünkü tezgâh rakamları "dün" olur */
  if ([2, 3, 5, 7, 10, 14, 21, 30].indexOf(day.n) >= 0) progEv('gun' + day.n);
  pickFeatured();
  pickSpecials();
  toptanDay();                                     /* v2.18-deneme: günlük toptan kuru + parti sayacı */
  day.market = isMarketDay(day.n);
  insDue();                                        /* v2.18-deneme: gün başında biten inşaatlar tamamlanır */
  day.st = newDayStats();
  day.t = 0;
  TAX.on = false;
  if (day.n % TAX_EVERY === TAX_EVERY - 1 && (taxQ().items > 0 || taxDebtNext() > 0)) setTimeout(function () {   /* v2.14: bir gün önceden haber */
    var dn = taxDebtNext(); toast(dn > 0 ? T(taxLastWeek() ? 'taxWarnLast' : 'taxWarnDebt', { v: money(dn) }) : T('taxWarn'));
  }, 2600);
  if (day.market && !skipPrep) { day.phase = 'prep'; showPrepCard(); return; }
  day.phase = 'intro'; day.ph = 1.7;
  sfx.dayIn();
  syncPause();
  if (undecidedStalls().length) openStallScreen();   /* gün başı: yeni tezgâh kararı */
}

