/* =========================================================
   İSTASYONLAR
   ========================================================= */
function tableTypes(t) { return zoneFish(t.z).filter(function (f) { return lineLive(f); }).length; }
function pileCap(t) { var st = slotEff(t.z, 'stock') || 0; return tableTypes(t) > 1 ? 8 + Math.round(st / 2) : 16 + st; }
