      if (!nf) continue;                      /* açık hat yoksa bu ağ üretmez */
      var it = { k: 'fish', f: nf };
      s.stock.push(it); S.caught++;
      var ox = s.face === 'n' ? s.x + rnd(-1, 1) : s.x - rnd(2, 3.2);
      var oy = s.face === 'n' ? s.y - rnd(2, 3.2) : s.y + rnd(-1, 1);
      fly(ox, oy, 2, s.x, s.y + 0.9, 8, it, 0.55);
