  /* v2.0 — gerçek liman kurumları */
  koop:   ['....kkkk....','...kwwwwk...','..kwwwwwwk..','.kkkkkkkkkk.','.kssssssssk.','.ks.kkkk.sk.','.ks.kggk.sk.','.ks.kggk.sk.','.kkkkkkkkkk.','..kk....kk..','............','............'],
