  ctx.restore();
  /* v0.1: ıslak kum bandı — kara/deniz geçişini yumuşatır */
  ctx.save();
  ctx.globalAlpha = 0.5;
  ctx.strokeStyle = '#b8a97e'; ctx.lineWidth = 7;
  ctx.beginPath();
  ctx.moveTo(R(pX(LANDX - 0.15, -0.55)), R(pY(LANDX - 0.15, -0.55, 0)));
