  for (var i = 0; i < SONGS.length; i++) h += '<button data-p="' + i + '"' + (musicPick === i ? ' class="on"' : '') + '>' + (now === i ? '♪ ' : '') + escH(NM(SONGS[i].n)) + '<small>' + escH(NM(SONGS[i].d)) + '</small></button>';
