var SPEC_WALK = 1.3, SPEC_LEAVE = 1.7;
function sayDur(txt) { return clamp(2.2 + (txt || '').length * 0.075, 4, 9); }
function specMeDur(cu) { var sp = specById(cu.spec); return sp && cu.intro && sp.me ? sayDur(NM(sp.me)) : 0; }
