  MGR_DESKS.forEach(function (d, z) { R.push({ id: 'müdür masası ' + z, own: 'md' + z, z: z, x0: d.x - 0.5, y0: d.y - 1.0, x1: d.x + 0.5, y1: d.y + 0.3 }); });
