  if (o.st === 'kiler') uiQ.push({ t: 4, x: o.x, y: o.y, z: 34, s: T('tfStKiler'), c: Math.sin(gameT * 5) > 0 ? '#ff9b8a' : '#ffd0c8', a: 1 });
  else if (o.st === 'nobody' && d < 30) uiQ.push({ t: 5, x: o.x, y: o.y, z: 34, s: '⏸ ' + T('tfStNobody'), c: '#dcdcd6', a: 0.92 });
