    q(-4, -2, 8, 1, '#2f5136'); q(-3, -2, 2, 1, '#4f7a4f'); dot(x + 1 * s, y - 2 * s, '#ffc94a'); dot(x + 3 * s, y - 2 * s, '#ffc94a');
