/* açılış akışı: kayıt yoksa gazete hikâyesi → ana menü. "Yeni Oyun" ile silinip gelindiyse
   hikâye → doğrudan işletme adı (oyuncu zaten yeni oyun dedi). */
/* v1.9 ilk açılış: önce dil seçimi (büyük iki düğme), sonra doğrudan gazete hikâyesi, sonra ana menü.
   Dil düğmesine dokunmak ses için gereken kullanıcı hareketini de sağlar; "başlamak için dokun" kapısı atlanır. */
var LANGPICK_KEY = 'balikci_langpick';
function openLangPick() {
  var lp = document.getElementById('langPick'), sug = /^tr/i.test(navigator.language || 'tr') ? 'tr' : 'en';
  Array.prototype.forEach.call(lp.querySelectorAll('button'), function (b) {
    b.classList.toggle('sug', b.dataset.l === sug);
    b.onclick = function () {
      Store.set(LANGPICK_KEY, '1'); lp.classList.add('hidden');
      setLangTo(b.dataset.l); ensureAudio(); sfx.tap();
      openIntro(null); introAdvance();                 /* kapıyı atla: hikâye hemen başlar */
    };
  });
  el.startScreen.classList.add('hidden');
  lp.classList.remove('hidden');
}
(function bootFlow() {
  if (slotCount()) return;                        /* kayıtlı oyuncu: doğrudan ana menü */
  if (!Store.get(LANGPICK_KEY)) openLangPick();   /* ilk açılış: dil → hikâye → ana menü */
  else openIntro(null);
})();
/* =========================================================
   v2.13 — İNCE PİKSEL KANCALARI (mimar)
   Her çizim fonksiyonu sarılır: ince ölçekli tuvalde (curK > 1) ve window.HKA[ad] tanımlıysa önce o çağrılır;
   false dönerse ya da hata atarsa klasik çizim yapılır (hata bir kez konsola uyarı olarak yazılır, oyun durmaz).
   Sanatçı dosyaları (art/*.js) oyunun içine HKG köprüsüyle bakar; oyun mantığına yazmazlar.
   ========================================================= */
var CLASSIC = {}, _artErr = {};
function hook(name, f0) {
  CLASSIC[name] = f0;
  return function (a, b, c, d, e, f, g) {
    var H = window.HKA, fn;
    if (curK > 1 && H && (fn = H[name])) {
      try { var r = fn(a, b, c, d, e, f, g); if (r !== false) return r; }   /* bina çizicileri yükseklik döndürür */
      catch (err) { if (!_artErr[name]) { _artErr[name] = 1; console.warn('HKA.' + name + ':', err && err.message); } }
    }
    return f0(a, b, c, d, e, f, g);
  };
}
/* v2.20-deneme: lokanta kancaları yeni (karada, ev + teras) yerleşimde. Eski iskele sanatı (HKA.drawLokanta/Table/Station/Crew/Fix) yeni yerleşime göre çizilmediğinden
   ince modda DEVRE DIŞI (klasik çizim görünür); her kancaya o.v2 = true verilir. Ana sanatçı yeni yerleşimi çizince HKA.lokV2 = true koyar → kancalar yeniden çağrılır
   (o.v2 true gelir; kanca yine false dönebilir). Yeni kancalar HKA.drawLokHouse / HKA.drawLokTerrace bu kapıya bağlı değildir. */
/* v2.22-deneme: ev ve teras yeni yerleşimde (gerçek koordinat). İnce çizim ancak yeni yerleşime geçince (HKA.lokV3) kullanılır; o zamana dek klasik */
function hookV3(name, f0) {
  var h = hook(name, f0);
  return function (o) {
    if (o && typeof o === 'object') o.v3 = true;
    if (!(window.HKA && HKA.lokV3)) return f0(o);
    return h(o);
  };
}
function hookLok(name, f0) {
  var h = hook(name, f0);
  return function (o) {
    if (o && typeof o === 'object') o.v2 = true;
    if (window.HKA && !HKA.lokV2) return f0(o);
    return h(o);
  };
}
